import { balanceDue } from './payments.js';
import { daysBetween } from './dates.js';
import { lineTotal } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Get invoices that are overdue as of a given date.
 * @param {Array} invoices - array of invoice objects
 * @param {string} asOf - date in YYYY-MM-DD format to check overdue status against
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>}
 */
export function overdueInvoices(invoices, asOf) {
  const overdue = invoices
    .filter((invoice) => (invoice.status === 'issued' || invoice.status === 'partially_paid') && invoice.dueDate < asOf)
    .map((invoice) => ({
      number: invoice.number,
      customerId: invoice.customerId,
      dueDate: invoice.dueDate,
      daysOverdue: daysBetween(invoice.dueDate, asOf),
      due: balanceDue(invoice),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return overdue;
}

/**
 * Get a summary of VAT by rate across invoices.
 * @param {Array} invoices - array of invoice objects
 * @returns {Array<{ rate: number, base: number, vat: number }>} entries sorted by rate descending
 */
export function vatSummary(invoices) {
  const vatMap = {};

  invoices
    .filter((invoice) => invoice.status === 'issued' || invoice.status === 'partially_paid' || invoice.status === 'paid')
    .forEach((invoice) => {
      invoice.lines.forEach((line) => {
        const rate = line.vatRate;
        const lineBase = lineTotal(line);
        const discountPercent = line.discountPercent ?? 0;
        const lineDiscount = roundCents(lineBase * (discountPercent / 100));
        const baseAmount = lineBase - lineDiscount;
        const vatAmount = roundCents(baseAmount * (rate / 100));

        if (!vatMap[rate]) {
          vatMap[rate] = { rate, base: 0, vat: 0 };
        }
        vatMap[rate].base += baseAmount;
        vatMap[rate].vat += vatAmount;
      });
    });

  return Object.values(vatMap)
    .map((entry) => ({
      rate: entry.rate,
      base: entry.base,
      vat: entry.vat,
    }))
    .sort((a, b) => b.rate - a.rate);
}

