test('vatSummary combines same rate from multiple invoices', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued1 = issueInvoice(r1.value, ['INV-2026-0001']);

  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  });
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001', 'INV-2026-0002']);

  const result = vatSummary([issued1.value, issued2.value]);
  assert.equal(result.length, 1);
  assert.equal(result[0].rate, 21);

  const line1Total = lineTotal(issued1.value.lines[0]);
  const line1Discount = roundCents(line1Total * (issued1.value.lines[0].discountPercent / 100));
  const line1Base = line1Total - line1Discount;

  const line2Total = lineTotal(issued2.value.lines[0]);
  const line2Discount = roundCents(line2Total * (issued2.value.lines[0].discountPercent / 100));
  const line2Base = line2Total - line2Discount;

  const expectedBase = line1Base + line2Base;
  assert.equal(result[0].base, expectedBase);
});

