test('lateFee calculates correctly for 1 day overdue', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const issued = issueInvoice(r.value, []);
  const dueDate = issued.value.dueDate;
  const due = balanceDue(issued.value);
  const expectedFee = roundCents(due * 1 * 0.0004);

  const result = lateFee(issued.value, issued.value.dueDate.substring(0, 10).split('-').map((n, i) => {
    if (i === 2) return String(Number(n) + 1).padStart(2, '0');
    return n;
  }).join('-'));

  assert.equal(result, expectedFee);
});

